class ParseError(ValueError):
    """A line of the ledger is not valid. ``line`` is its 1-based number."""

    def __init__(self, line, message):
        self.line = line
        self.reason = message
        super().__init__("line {}: {}".format(line, message))


@dataclass(frozen=True)
class Entry:
    date: datetime.date
    category: str
    amount: Decimal
    note: str = ""


def check_date(text):
    """Return the ``datetime.date`` for ``YYYY-MM-DD`` text or raise ValueError."""
    if not _DATE_RE.match(text):
        raise ValueError("invalid date {!r} (expected YYYY-MM-DD)".format(text))
    try:
        return datetime.date(int(text[0:4]), int(text[5:7]), int(text[8:10]))
    except ValueError:
        raise ValueError("invalid date {!r} (no such day)".format(text)) from None


def check_amount(text):
    """Return the Decimal for amount text or raise ValueError."""
    if not _AMOUNT_RE.match(text):
        raise ValueError(
            "invalid amount {!r} (expected a number with at most two decimals)".format(text)
        )
    if len(text.lstrip("+-").split(".")[0].lstrip("0")) > MAX_INTEGER_DIGITS:
        raise ValueError(
            "amount too large (at most {} digits before the decimal point)".format(
                MAX_INTEGER_DIGITS
            )
        )
    return Decimal(text)

